item.content:encoded:
.wp-block-separator {
	color: #e5e5e5;
}

.icon-32 {
  font-size: 32px;
  top: 5px;
  position: relative;
	margin-right: 5px;
}

.column-icons {
  font-size: 40px;
	color: #002c77;
}

.sm-top-margin {
	margin-top: 4px;
}

h1, h2, h3, h4, h5 {
	margin-bottom: 18px !important;
}

body {
	line-height: 1.7em;
}

.et_pb_post a {
	color: #2ea3f2;
}

.pagination a {
	color: #53a1ec !important;
	margin-right: 30px;
}

.more-link {
	text-transform: capitalize;
}

.et_pb_section a {
	color: #2ea3f2 !important;
}

#top-menu li.mega-menu>ul {
    padding: 30px 20px;
    position: absolute !important;
    width: 100%;
    left: 20% !important;
}

.sub-menu {
    width: 60% !important;
    left: 0 !important;
	margin-left: auto;
	margin-right: auto;
}

#mobile_menu .menu-item a {
    color: white !important;
}

.sub-menu > .menu-item > a {
	color: white !important;
}

#main-header .nav li ul a {
    line-height: 1.5;
}

.et_mobile_menu li a:hover, .nav ul li a:hover {
    background-color: rgba(0, 0, 0, .15) !important;
    opacity: .9 !important;
}

.notALink2 > a {
	display: none !important;
}

.notALink > a {
	font-family: 'Source Serif 4', Georgia, "Times New Roman", serif;
	font-size: 18px !important;
	opacity: .8;
}

.notALink > a:hover {
    cursor: default !important;
	opacity: 1 !important;
}

.menu-items a:hover {
    cursor: pointer !important;
}

#main-header .nav li ul a:hover {
    color: #001f65;
	opacity: 1 !important;
}

.post-template-default > #page-container > .et-boc > #main-header {
	background-color: #0e2b72 !important;
}

.sub-menu {
	background-color: #0e2b72 !important;
	color: white !important;
	width: auto !important;
}

.mega-menu a {
	color: white !important;
}

.blog > #page-container > .et-boc > #main-header {
	background-color: #0e2b72 !important;	
}

.search-results > #page-container > .et-boc > #main-header {
	background-color: #0e2b72 !important;	
}

.post-type-archive-project > #page-container > .et-boc > #main-header {
	background-color: #0e2b72 !important;
}

.search-no-results > #page-container > .et-boc > #main-header {
	background-color: #0e2b72 !important;	
}


.mobile_menu_bar::before {
	color: white !important;
}

#et_search_icon::before {
	color: white !important;
}

#cookie-notice {
 z-index: 10 !important;
}

.et_primary_nav_dropdown_animation_fade #et-top-navigation ul li:hover>ul {
	background-color: #0e2b72 !important;
	color: white !important;
}

.et_mobile_menu {
overflow: scroll !important;
max-height: 80vh;
}

@media only screen and (max-width: 980px) {
    #main-header {
        background-color: #0e2b72;
    }
	.sub-menu {
		width: 100% !important;
	}
}

@media only screen and (max-width: 600px) {
    .entry-title {
        font-size: 30px;
    }
}

@media (max-width: 767px) {
    body.admin-bar.et_fixed_nav #main-header {
        background-color: #0e2b72 !important;
    }
}

@media only screen and (max-width:980px) {
    #main-header, #main-header .nav li ul, .et-search-form, #main-header .et_mobile_menu {
        background-color: #0e2b72 !important;
    }
	.et_primary_nav_dropdown_animation_fade #et-top-navigation ul li:hover>ul {
    background-color: transparent !important;
}
	    .et_fixed_nav #main-header {
        position: fixed;
    }
}

