}

.et_pb_preload .et_pb_section_video_bg {
visibility: visible;
background: url("https://www.mandsconsulting.com/wp-content/uploads/static-hero.jpg") no-repeat !important;
background-size: cover !important;
}

.et_pb_preload .mejs-container {
background: transparent !important;
}

